import { Soundtrack, type Cue } from "../shared/Soundtrack";
import { VOICE_CLIPS } from "./captions";
import { BLAST, FPS, HITS, IGNITION, SCENE_STARTS, SHOCK_ARRIVES } from "./constants";

// Score and SFX are generated by `node scripts/generate-audio.mjs nuke` into
// public/whatif-nuke/. The score cuts out on the flash (12.6s).

const s = (scene: number, seconds: number) => Math.round(SCENE_STARTS[scene] + seconds * FPS);

const CUES: Cue[] = [
  // Whoosh on every cut
  ...SCENE_STARTS.slice(1).map((start) => ({ at: start - 10, src: "whatif-nuke/whoosh.mp3", volume: 0.5 })),
  // Launch roar
  { at: s(0, IGNITION - 0.1), src: "whatif-nuke/rumble.mp3", volume: 0.55 },
  // Air-raid siren through the street scene
  { at: s(1, -0.25), src: "whatif-nuke/siren.mp3", volume: 0.3 },
  // Interceptors: the zap's pop lands on each hit
  ...HITS.map((hit) => ({ at: s(2, hit - 0.45), src: "whatif-nuke/zap.mp3", volume: 0.45 })),
  // Silent flash first, boom when the shockwave reaches us
  { at: s(3, SHOCK_ARRIVES - 0.05), src: "whatif-nuke/boom.mp3", volume: 0.7 },
  { at: s(3, BLAST + 0.1), src: "whatif-nuke/rumble.mp3", volume: 0.18 },
  // Cold wind
  { at: s(4, 0), src: "whatif-nuke/wind.mp3", volume: 0.4 },
];

export const SoundEffects: React.FC = () => (
  <Soundtrack music="whatif-nuke/score.mp3" voice={VOICE_CLIPS} cues={CUES} musicVolume={0.55} duckedVolume={0.16} />
);
